async function refresh(){try{state=await api('/control/state');render()}catch(e){toast('Falha ao atualizar: '+e.message)}}async function post(url,body){try{const x=await api(url,{method:'POST',body:body?JSON.stringify(body):'{}'});await refresh();return x}catch(e){toast(e.message);return null}}
